INSERT INTO "alocacao" VALUES(134,51,2,1,'VIDA Análise ca/ fabetização) Semiótica Linguísti (Al','','','em Identificação da formatação e O foco da diagramação de cartazes e fo prios dos gêneros ao lhetos. dá no interior de dante venha a empregá-los','visa propiciar ao estudante o reconhecimento dos recursos gráficos pró cartazes e folhetos, com vistas à sua apropriação. Seu desenvolvimento só se práticas de leitura, análise e produção desses textos, permitindo que o estu adequadamente em sua própria escrita.','dct linguagens.pdf',74);
INSERT INTO "alocacao" VALUES(135,68,2,1,'OS PÚBLICA/TODOS VIDA ATUAÇÃO DE CAMPOS Análise ca/ fabetização) Semiótica Linguísti (Al','','','Construção do sistema al A partir dos gêneros fabético e da ortografia. tizando procedimentos as Leitura e escrita de palavras de compreensão com sílabas CVC, CCV. o sistema de escrita Recomenda-se que além disso, a análise distintos pelo estudante.','trabalhados anteriormente, o professor aprofundará essa enfa de análise comparativa da escrita que potencializam as possibilidades e avanço do estudante, organizando atividades para que ele compreenda que também envolve a compreensão da ordem das letras na palavra e na sílaba. priorize a análise e comparação entre escritas estáveis e as do estudante e, de escritas diferentes de uma mesma palavra, realizadas em momentos','dct linguagens.pdf',74);
INSERT INTO "alocacao" VALUES(136,33,2,1,'OS PÚBLICA/TODOS VIDA ATUAÇÃO DE CAMPOS Análise ca/ fabetização) Semiótica Linguísti (Al','','','Leitura e compreensão do gêne do ro textual entrevista. pe en e o','O trabalho com essa já foi iniciado no primeiro ano com foco em outros gêneros, no segundo ano poderá aprimorá-la com a leitura e compreensão de entrevistas, articulando-os a identificação de situação comunicativa; tema/assunto; forma de organização; finalidade do texto. O trabalho envolve ao menos duas operações distintas, que podem ser tratadas em separado: planejar e produzir, que significam organizar as ideias para depois colocá-las no papel. O pla nejamento e a produção podem ser organizados de modo coletivo e de forma interdisciplinar.','dct linguagens.pdf',75);
INSERT INTO "alocacao" VALUES(137,77,2,1,'Leitura/escuta (compartilhada autônoma) e','','','tex Imagens analíticas em textos. Reconhecimento da função de pequenas entrevistas e/ ou en quetes, registro de experimen tações em atividades de pesqui sa.','Trata-se de reconhecer que os textos utilizados para apresentar informações coletadas em ati vidades de pesquisa possuem funções relacionadas ao ao qual pertencem. Assim, é necessário caracterizar o das entrevistas e sua respectiva função, analisar o tipo de informações que apresentam e identificar a função específica da entrevista.','dct linguagens.pdf',75);
INSERT INTO "alocacao" VALUES(138,78,2,1,'PESQUISA E ESTUDO','','','do Pesquisa referente ao tema in vestigado. Exploração de textos informati vos nos ambientes digitais.','Trata-se de estudar textos informativos de ambientes digitais, como revistas, jornais, sites es pecializados e orientados para crianças e blogs confiáveis. O objetivo é a exploração de recur sos, como para outros textos e para vídeos, o modo de organização das informações e as possibilidades e limites dos recursos próprios da ferramenta e do site específico. Inicia-se hiperlinks o trabalho com o manuseio da ferramenta com o texto já aberto em trabalho colaborativo, no coletivo. Aos poucos, passa-se do coletivo para duplas e para o trabalho autônomo. Depois, po de-se iniciar o trabalho a partir do acesso ao ambiente e, no final, considerar textos e ambientes mais complexos.','dct linguagens.pdf',75);
INSERT INTO "alocacao" VALUES(139,71,2,1,'DE PRÁTICAS 75 Escrita lhada e (comparti autônoma)','','','Produção de textos referentes ao tema investigado. Gênero Entrevista. do','Uma atividade que pode ser proposta aos estudantes é a realização de pequenas entrevistas a partir de temas, curiosidades propostas pelos próprios estudantes, iniciando com planeja mento coletivo da textualização, pesquisas em ambientes digitais em colaboração e analises de entrevistas impressas e digitais.','dct linguagens.pdf',75);
