INSERT INTO "habilidade" VALUES(205,1,'EF67LP10','Produzir notícia impressa do em vista características do gênero ou manchete com verbo no tempo presente, linha fina (opcional), lide, progressão pela ordem decrescente de importância fatos, uso de 3ª pessoa, de palavras que cam precisão –, e o estabelecimento adequa do de coesão e produzir notícia para TV, e internet, tendo em vista, além das caracte rísticas do gênero, os recursos de mídias poníveis e o manejo de recursos de captação e edição de áudio e imagem.','BNCC','6,7');
INSERT INTO "habilidade" VALUES(206,1,'EF67LP32','Escrever palavras com correção ortográfica, obedecendo as convenções língua escrita.','BNCC','6,7');
INSERT INTO "habilidade" VALUES(207,1,'EF67LP33','Pontuar textos adequadamente.','BNCC','6,7');
