INSERT INTO "habilidade" VALUES(209,1,'EF67LP36','Utilizar, ao produzir texto, cursos de coesão referencial (léxica e minal) e sequencial e outros recursos expres sivos adequados ao gênero textual.','BNCC','6,7');
